import React, { useEffect, useRef } from 'react';
import { formatINR } from '../../data/centerMockData.js';
import { CopyButton } from '../common/Ui.jsx';

/**
 * ShowCauseNoticeModal
 * ---------------------------------------------------------------------------
 * Renders the officially formatted, digitally signed government document
 * generated by the enforcement engine — Show-Cause Notice, Grant Freeze Order
 * or Surprise Audit Order — complete with automated evidence annexures.
 *
 * Actions: 🖨️ print (A4 stylesheet), ⤓ download as .txt, 📋 copy, and a
 * jump-link to the centre's verification report.
 */
export default function ShowCauseNoticeModal({ open, doc, report, onClose, onJumpToCentre }) {
  const bodyRef = useRef(null);

  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => {
      if (e.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', onKey);
    document.body.style.overflow = 'hidden';
    return () => {
      window.removeEventListener('keydown', onKey);
      document.body.style.overflow = '';
    };
  }, [open, onClose]);

  if (!open || !doc) return null;

  const download = () => {
    const blob = new Blob([doc.body], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `${doc.ref.replace(/[^\w-]+/g, '_')}.txt`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
  };

  const print = () => {
    const node = bodyRef.current;
    if (!node) return;
    const win = window.open('', '_blank', 'width=900,height=1100');
    if (!win) {
      // Pop-up blocked (common in embedded previews) — fall back to in-page print
      window.print();
      return;
    }
    win.document.write(`<!doctype html><html><head><title>${doc.ref}</title>
      <style>
        body{font-family:"Times New Roman",Georgia,serif;font-size:13px;line-height:1.55;color:#111;padding:28px 34px;white-space:pre-wrap;}
        .lh{border-bottom:3px double #111;padding-bottom:8px;margin-bottom:16px;}
        .lh h1{margin:0;font-size:19px;letter-spacing:.4px;}
        .lh h2{margin:2px 0 0;font-size:14px;font-weight:600;}
        .lh span{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:#444;}
      </style></head><body>
      <div class="lh">
        <span>${doc.letterhead}</span>
        <h1>${doc.authority}</h1>
        <h2>${doc.department}</h2>
      </div>
      ${node.textContent.replace(/&/g, '&amp;').replace(/</g, '&lt;')}
      </body></html>`);
    win.document.close();
    win.focus();
    win.print();
  };

  const tone = doc.tone || 'amber';

  return (
    <div className="modal-backdrop" role="dialog" aria-modal="true" aria-label={doc.title}>
      <div className={`modal modal--${tone}`}>
        <header className="modal__head">
          <div className="modal__title-wrap">
            <span className="modal__seal">🏛️</span>
            <div>
              <h2 className="modal__title">{doc.title}</h2>
              <p className="modal__sub">
                {doc.letterhead} · Reference <b className="mono">{doc.ref}</b> · Issued{' '}
                {new Date(doc.issuedOn).toLocaleString('en-IN', { day: '2-digit', month: 'long', year: 'numeric', hour: '2-digit', minute: '2-digit' })}
              </p>
            </div>
          </div>
          <div className="modal__actions">
            <CopyButton text={doc.body} label="Copy text" />
            <button type="button" className="btn btn--ghost btn--sm" onClick={download}>
              ⤓ Download .txt
            </button>
            <button type="button" className="btn btn--primary btn--sm" onClick={print}>
              🖨️ Print / PDF
            </button>
            <button type="button" className="btn btn--ghost btn--sm modal__close" onClick={onClose} aria-label="Close notice">
              ✕
            </button>
          </div>
        </header>

        <div className="modal__meta-strip">
          <div>
            <span>Centre</span>
            <strong>{doc.centreName}</strong>
          </div>
          <div>
            <span>Amount at risk</span>
            <strong className="is-critical">{formatINR(doc.amountAtRisk || 0)}</strong>
          </div>
          <div>
            <span>{doc.action === 'audit' ? 'Inspection date' : 'Reply deadline'}</span>
            <strong>{doc.replyByLabel || '—'}</strong>
          </div>
          {doc.officer && (
            <div>
              <span>Issuing officer</span>
              <strong>
                {doc.officer.name}, {doc.officer.designation}
              </strong>
            </div>
          )}
          {report && (
            <div>
              <span>Verification report</span>
              <strong className="mono">{report.worst ? report.worst.reportId : '—'}</strong>
            </div>
          )}
        </div>

        <div className="modal__body">
          <article className="notice-sheet" ref={bodyRef}>
            <div className="notice-sheet__letterhead">
              <span>{doc.letterhead || 'MSDE Skilling Compliance Engine'}</span>
              <h1>{doc.authority || 'Government of India'}</h1>
              <h2>{doc.department || 'Ministry of Skill Development and Entrepreneurship'}</h2>
            </div>
            <pre className="notice-sheet__text">{doc.body}</pre>
            <div className="notice-sheet__sign">
              <div className="notice-sheet__qr" aria-hidden="true">
                <span className="notice-sheet__qr-grid" />
                <em>e-Sign hash verified</em>
              </div>
              {doc.officer ? (
                <div>
                  <strong>{doc.officer.name}</strong>
                  <span>
                    {doc.officer.designation}, {doc.officer.district}
                  </span>
                  <span className="mono">{doc.officer.email} · ☎ {doc.officer.phone}</span>
                </div>
              ) : (
                <div>
                  <strong>Digitally signed</strong>
                  <span>MSDE Compliance Engine</span>
                </div>
              )}
            </div>
          </article>
        </div>

        <footer className="modal__foot">
          <span className="modal__annex">
            Evidence annexures attached: edge telemetry JSON · face-redacted keyframes · infra scan log · SDMS ledger extract · GPS geofence log
          </span>
          {report && (
            <button
              type="button"
              className="btn btn--ghost btn--sm"
              onClick={() => {
                onJumpToCentre?.(report.centreId);
                onClose();
              }}
            >
              🔎 Open full verification report for {report.centreName}
            </button>
          )}
        </footer>
      </div>
    </div>
  );
}
